INSERT INTO [dbo].[ConnectorHealingLogs] (
    [Id], [QueueId], [ConnectorName], [EventType], [AttemptNo], [HealingStep],
    [Severity], [Message], [Details], [CreatedAt]
)
SELECT
    [Id],
    CASE [ConnectorName]
        WHEN 'TOPO-CLI-G042.009' THEN @QueueId042
        WHEN 'TOPO-CLI-G043.008' THEN @QueueId043
    END,
    [ConnectorName],
    [EventType],
    [AttemptNo],
    [HealingStep],
    CASE UPPER(CASE WHEN ISJSON([Details]) = 1 THEN JSON_VALUE([Details], '$.severity') END)
        WHEN 'ERROR' THEN 'ERROR'
        WHEN 'WARNING' THEN 'WARNING'
        WHEN 'WARN' THEN 'WARNING'
        ELSE 'INFO'
    END,
    [Message],
    [Details],
    [CreatedAt]
FROM @LegacyLogs AS l
WHERE NOT EXISTS (
    SELECT 1
    FROM [dbo].[ConnectorHealingLogs] AS existing_log
    WHERE existing_log.[Id] = l.[Id]
);

COMMIT TRANSACTION;

SELECT
    q.[RootConnectorName],
    q.[CurrentConnectorName],
    q.[QueueStatus],
    q.[FinalOutcome],
    COUNT(l.[Id]) AS [HealingLogCount]
FROM [dbo].[ConnectorHealingQueue] AS q
LEFT JOIN [dbo].[ConnectorHealingLogs] AS l
    ON l.[QueueId] = q.[QueueId]
WHERE q.[QueueId] IN (@QueueId042, @QueueId043)
GROUP BY
    q.[RootConnectorName],
    q.[CurrentConnectorName], q.[QueueStatus], q.[FinalOutcome]
ORDER BY q.[CurrentConnectorName];